-- Smash history: the missing places of 13 hand-added top 8s (Matthew, 2026-11-19: "continue with history"). Their
-- Liquipedia pages listed fewer than 8 (MLG Anaheim 2014 only its final, run with pool play); SmashWiki's
-- tournament pages have them, read by hand in Matthew's Chrome a few seconds apart: places and names only,
-- credited to SmashWiki (CC BY-SA). Places already saved keep their names (Liquipedia's spelling); only missing
-- places are added (2GGT: ZeRo Saga's 4th was ZeRo himself). MLG San Francisco 2004 has only 3 places on both.
-- A bracket is updated only while it still has fewer than 8 places and its 1st and 2nd still match. Safe to
-- run twice.

update public.major_events e
set top8 = v.top8
from (values
  ('manual/2014-mlg-anaheim-2014', 'manual-melee-1', 'Mango', 'Armada', '[{"place":1,"name":"Mango","playerId":null},{"place":2,"name":"Armada","playerId":null},{"place":3,"name":"Mew2King","playerId":null},{"place":4,"name":"PPMD","playerId":null},{"place":5,"name":"Leffen","playerId":null},{"place":5,"name":"Axe","playerId":null},{"place":7,"name":"Hax","playerId":null},{"place":7,"name":"Hungrybox","playerId":null}]'::jsonb, 'https://www.ssbwiki.com/Tournament:MLG_Anaheim_2014'),
