) as v (major_slug, event_id, first, second, top8, source_url)
where e.major_slug = v.major_slug and e.event_id = v.event_id
  and jsonb_array_length(e.top8) < 8
  and lower(e.top8->0->>'name') = lower(v.first) and lower(e.top8->1->>'name') = lower(v.second);
